[InitializeOnLoad] public static class V12BatchTools {
 const string Prefix="V12BatchTools."; static IEnumerator routine; static double due; static string issue;
 static V12BatchTools(){ EditorApplication.update+=Tick; Application.logMessageReceived+=(m,s,t)=>{if(SessionState.GetBool(Prefix+"running",false)&&(t==LogType.Exception||t==LogType.Error)) File.AppendAllText("Temp/V12/runtime-errors.txt",m+"\n"+s+"\n");}; }
 static void Tick(){try{
 if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;
 const string flag="Temp/v12-batch.flag";
 if(File.Exists(flag)){string action=File.ReadAllText(flag).Trim();File.Delete(flag);
 if(action.StartsWith("test")){issue=action.Substring(4);SessionState.SetString(Prefix+"issue",issue);SessionState.SetInt(Prefix+"stage",0);SessionState.SetBool(Prefix+"running",true);File.WriteAllText("Temp/V12/runtime-errors.txt","");EditorSceneManager.OpenScene("Assets/_Project/Scenes/Main Menu.unity");EditorApplication.EnterPlaymode();return;}
 typeof(V12Checks).GetMethod(action).Invoke(null,null);File.WriteAllText("Temp/V12/done.txt",action+" PASS"); }
 if(!SessionState.GetBool(Prefix+"running",false)||EditorApplication.timeSinceStartup<due)return;
 issue=SessionState.GetString(Prefix+"issue","");int stage=SessionState.GetInt(Prefix+"stage",0);
 if(stage==0&&EditorApplication.isPlaying){if(!InteractionManager.Instance)return;var launch=Resources.FindObjectsOfTypeAll<MainMenuExperimentLauncher>().First(l=>l.gameObject.scene==SceneManager.GetActiveScene()&&new SerializedObject(l).FindProperty("storyboardId").stringValue=="Speed Curve Characteristics");InteractionManager.Instance.currentMode=ExperimentMode.Guided;launch.GetComponent<Button>().onClick.Invoke();SessionState.SetInt(Prefix+"stage",1);due=EditorApplication.timeSinceStartup+4;return;}
 if(stage==1&&EditorApplication.isPlaying){routine=(IEnumerator)typeof(V12Checks).GetMethod("Test"+issue).Invoke(null,null);SessionState.SetInt(Prefix+"stage",2);}
 if(stage==2){if(routine.MoveNext()){due=EditorApplication.timeSinceStartup+(routine.Current is float f?f:0);return;} var errors=File.ReadAllText("Temp/V12/runtime-errors.txt");if(errors.Length>0)throw new Exception(errors);File.AppendAllText("Reports/V12Fixes/"+issue+".txt","PASS: no runtime errors.\n");SessionState.SetInt(Prefix+"stage",3);EditorApplication.ExitPlaymode();return;}
 if(stage==3&&!EditorApplication.isPlayingOrWillChangePlaymode){EditorSceneManager.OpenScene("Assets/_Project/Scenes/PV Lab.unity");SessionState.SetBool(Prefix+"running",false);File.WriteAllText("Temp/V12/done.txt","test"+issue+" PASS");}
 }catch(Exception e){File.WriteAllText("Temp/V12/done.txt","FAIL "+e);SessionState.SetBool(Prefix+"running",false);if(EditorApplication.isPlaying)EditorApplication.ExitPlaymode();}}
}
public static class V12Checks {
 public static T[] All<T>() where T:UnityEngine.Object=>Resources.FindObjectsOfTypeAll<T>().Where(x=>x is Component c&&c.gameObject.scene==SceneManager.GetActiveScene()).ToArray();
 public static object Get(object o,string n)=>o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(o);
 public static void Set(object o,string n,object v)=>o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).SetValue(o,v);
 public static object Call(object o,string n,params object[] a)=>o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(o,a);
 public static void Require(bool ok,string message){if(!ok)throw new Exception(message);}
 public static void Report(string n,string text){Directory.CreateDirectory("Reports/V12Fixes");File.AppendAllText("Reports/V12Fixes/"+n+".txt",text+"\n");}
 public static IEnumerator Test5(){var toggle=All<WireMaterialTransparencyToggle>().Single();for(int mode=0;mode<2;mode++){
 if(mode==1){InteractionManager.Instance.SetFree();yield return 3f;}
 toggle=All<WireMaterialTransparencyToggle>().Single();for(var t=toggle.transform;t;t=t.parent)t.gameObject.SetActive(true);yield return .1f;toggle.GetComponent<Button>().onClick.Invoke();int count=0;foreach(var cable in All<UnityEngine.Splines.SplineExtrude>()){var r=cable.GetComponent<Renderer>();if(!r)continue;foreach(var m in r.sharedMaterials){if(!m)continue;Require(!m.HasProperty("_Color")||Mathf.Abs(m.color.a-.4f)<.001f,"Opaque wire "+cable.name);Require(m.renderQueue==3000,"Opaque queue "+cable.name);count++;}}
 toggle.GetComponent<Button>().onClick.Invoke();foreach(var cable in All<UnityEngine.Splines.SplineExtrude>()){var r=cable.GetComponent<Renderer>();if(r)foreach(var m in r.sharedMaterials)if(m&&m.HasProperty("_Color"))Require(m.color.a>.999f,"Not restored "+cable.name);}
 Report("5-button","PASS actual UI button "+(mode==0?"Guided":"Free")+": "+count+" spline material slots transparent at 0.4 and restored opaque; includes inactive cables.");}}
 public static IEnumerator Test33(){foreach(var speed in All<WindTurbineSpeedController>().Where(s=>s.HasWindModel)){var audio=(AudioSource)Get(speed,"windMillAudio");Require(audio,"Missing wind audio "+speed.name);audio.loop=false;speed.TurnOn();speed.SetSpeed(200);Require(audio.loop,"Not looping");speed.TurnOff();Require(!audio.isPlaying,"Sound did not stop");}Report("33","PASS all four Guided controllers enforce loop on playback and stop on power off. Free Mode retains its existing loop=true source.");yield break;}
 public static IEnumerator Test53(){var root=new GameObject("Isolated quiz check");root.SetActive(false);var quiz=root.AddComponent<MultipleChoiceQuiz>();var q=new MultipleChoiceQuiz.Question{questionObject=new GameObject("Question")};q.questionObject.transform.SetParent(root.transform);for(int i=0;i<3;i++){var go=new GameObject("Answer"+i,typeof(RectTransform),typeof(Button));go.transform.SetParent(q.questionObject.transform);foreach(var name in new[]{"Correct","Incorrect"})new GameObject(name).transform.SetParent(go.transform);q.answers.Add(new MultipleChoiceQuiz.Answer{button=go.GetComponent<Button>(),correct=i==2});}quiz.questions.Add(q);Set(quiz,"nextQuestionDelay",.05f);root.SetActive(true);yield return .1f;
 q.answers[0].button.onClick.Invoke();Require(q.answers[0].incorrectHighlight.activeSelf,"Wrong choice not red");Require(!q.answers[1].incorrectHighlight.activeSelf&&!q.answers[2].correctHighlight.activeSelf,"Unclicked answer highlighted");yield return .1f;Require((int)Get(quiz,"currentQuestion")==0&&q.questionObject.activeSelf,"Wrong answer advanced");q.answers[2].button.onClick.Invoke();Require(q.answers[2].correctHighlight.activeSelf&&!q.answers[0].incorrectHighlight.activeSelf,"Correct answer highlight");yield return .1f;Require((int)Get(quiz,"currentQuestion")==1,"Correct answer did not advance");UnityEngine.Object.Destroy(root);Report("53","PASS wrong choice highlights only itself and stays on question; correct choice uses its Correct child and advances once after delay.");}
 public static void Fix20(){var tabs=All<WindMonitorTabs>().Single();var so=new SerializedObject(tabs);var system=(Interaction)so.FindProperty("systemButton").objectReferenceValue;var template=system.transform.Find("Selection Tab");Require(template,"System Selection Tab missing");template.gameObject.SetActive(true);so.FindProperty("systemSelectionTab").objectReferenceValue=template.gameObject;var entries=so.FindProperty("experiments");for(int i=0;i<entries.arraySize;i++){var e=entries.GetArrayElementAtIndex(i);var button=(Interaction)e.FindPropertyRelative("graphButton").objectReferenceValue;var marker=button.transform.Find("Selection Tab");if(!marker){marker=UnityEngine.Object.Instantiate(template,button.transform,false);marker.name="Selection Tab";}marker.gameObject.SetActive(false);e.FindPropertyRelative("selectionTab").objectReferenceValue=marker.gameObject;}so.ApplyModifiedPropertiesWithoutUndo();EditorSceneManager.SaveScene(SceneManager.GetActiveScene());Report("20","Scene: System Selection Tab on by default; each of four graph buttons has its own Selection Tab reference.");}
 public static IEnumerator Test20(){var tabs=All<WindMonitorTabs>().Single();var so=new SerializedObject(tabs);var system=(GameObject)so.FindProperty("systemSelectionTab").objectReferenceValue;var entries=so.FindProperty("experiments");Require(system.activeSelf,"System default marker off");tabs.SetPageSelection(true);Require(!system.activeSelf,"System marker remained on");for(int i=0;i<entries.arraySize;i++)Require(((GameObject)entries.GetArrayElementAtIndex(i).FindPropertyRelative("selectionTab").objectReferenceValue).activeSelf,"Graph marker off");tabs.SetPageSelection(false);Require(system.activeSelf,"System marker not restored");var button=(Interaction)entries.GetArrayElementAtIndex(0).FindPropertyRelative("graphButton").objectReferenceValue;button.Allow=false;tabs.ShowGraph(button);Require(!((bool)Get(tabs,"graphShown")),"EXP1 graph unlocked early");InteractionManager.Instance.SetFree();yield return 3f;tabs=All<WindMonitorTabs>().Single();system=(GameObject)new SerializedObject(tabs).FindProperty("systemSelectionTab").objectReferenceValue;var wind=FreeLabWindController.Instance;wind.mainEmergency.SetValue(true);wind.mainBreaker.SetValue(true);wind.mainPower.SetValue(true);wind.Refresh();wind.ShowGraph();Require(!system.activeSelf&&wind.graphPage.activeSelf&&!wind.monitors.activeSelf,"Free graph toggle");wind.ShowSystem();Require(system.activeSelf&&!wind.graphPage.activeSelf&&wind.monitors.activeSelf,"Free system toggle");Report("20","PASS exclusive selection indicators, EXP1 initial graph lock, Free Mode graph/system round trip.");}
 public static IEnumerator Test30(){var source=All<ExperimentMenuTabHighlight>().First(h=>h.name=="Documents");var go=new GameObject("Isolated Documents selection check",typeof(RectTransform),typeof(Toggle),typeof(Animator));var animator=go.GetComponent<Animator>();animator.runtimeAnimatorController=source.GetComponent<Animator>().runtimeAnimatorController;var highlight=go.AddComponent<ExperimentMenuTabHighlight>();var toggle=go.GetComponent<Toggle>();toggle.isOn=true;yield return .1f;animator.Play("Normal",0,0);animator.Update(0);Call(highlight,"LateUpdate");animator.Update(0);Require(animator.GetCurrentAnimatorStateInfo(0).IsName("Highlighted"),"Selected Documents lost its highlight after another control sent Normal");toggle.isOn=false;highlight.OnPointerExit(null);yield return .1f;Require(!toggle.isOn,"Toggle reselected unexpectedly");Require(!animator.GetCurrentAnimatorStateInfo(0).IsName("Highlighted"),"Deselected Documents stayed highlighted");UnityEngine.Object.Destroy(go);Report("30","PASS selected Documents animation survives a Normal/focus-loss event; actual deselection clears the highlight.");}
public static IEnumerator Test32(){InteractionManager.Instance.SetFree();yield return 3f;var wind=FreeLabWindController.Instance;int count=0;foreach(var socket in wind.sockets.Where(s=>s.plugs.Length>1)){var ep=socket.endpoint;Require(ep.TryAcquireConnectionPlug(out var first),"No first plug "+ep.name);ep.SetSelectionPlugVisible(true);var second=socket.plugs[1];Require(first.activeInHierarchy&&second.activeInHierarchy,"Second click preview hidden: "+ep.name);var renderers=second.GetComponentsInChildren<Renderer>(true);Require(renderers.Any(r=>r.enabled&&r.gameObject.activeInHierarchy),"Second plug has no visible renderer: "+ep.name);Require(ep.TryAcquireConnectionPlug(out var acquired)&&acquired==second,"Second slot allocation wrong: "+ep.name);ep.SetSelectionPlugVisible(false);Require(first.activeInHierarchy&&second.activeInHierarchy,"Second completed plug hidden: "+ep.name);Require(Vector3.Distance(first.transform.position,second.transform.position)>.5f,"Second plug overlaps first body: "+ep.name);Report("32",ep.name+" first="+first.transform.position+" second="+second.transform.position+" separation="+Vector3.Distance(first.transform.position,second.transform.position));ep.ReleaseConnectionPlug(first);ep.ReleaseConnectionPlug(second);count++;}Report("32","PASS "+count+" pools acquire/preview two active plug renderers.");foreach(var profile in wind.profiles){var groups=profile.required.Concat(profile.alternatives.Select(a=>a.alternatives.First()));foreach(var d in groups.SelectMany(g=>g.RequiredWires).Distinct()){d.endpointA.Interaction.Click();d.endpointB.Interaction.Click();Require(wind.lab.HasConnection(d.endpointA,d.endpointB),"Actual endpoint clicks failed "+d.name);}foreach(var wire in wind.lab.Connections.ToArray())Require(wire.RemoveFromFreeLab(),"Wire removal failed after slot allocation");Require(wind.lab.ConnectionCount==0,"Slots not released");}Report("32","PASS all four profiles connect using actual endpoint clicks and remove/release all allocated slots.");}
 public static void Inspect(){if(SceneManager.GetActiveScene().name!="PV Lab")EditorSceneManager.OpenScene("Assets/_Project/Scenes/PV Lab.unity");var wind=All<FreeLabWindController>().Single();var b=new System.Text.StringBuilder();foreach(var socket in wind.sockets.Where(s=>s.plugs.Length>1))b.AppendLine("STACK "+socket.endpoint.name+" first="+socket.plugs[0].transform.position.ToString("F3")+" second="+socket.plugs[1].transform.position.ToString("F3")+" delta="+Vector3.Distance(socket.plugs[0].transform.position,socket.plugs[1].transform.position));foreach(var r in All<RheostatController>().Where(r=>V12FixRunner.Path(r.transform).StartsWith("Experiments/"))){b.AppendLine("RHEOSTAT "+V12FixRunner.Path(r.transform));foreach(var c in r.GetComponentsInChildren<Canvas>(true))b.AppendLine("  CANVAS "+V12FixRunner.Path(c.transform));}foreach(var page in wind.pages){b.AppendLine("PAGE "+V12FixRunner.Path(page.root.transform));foreach(var c in page.root.GetComponentsInChildren<Collider>(true))b.AppendLine(" COLLIDER "+V12FixRunner.Path(c.transform)+" enabled="+c.enabled+" handlers="+string.Join(",",c.GetComponents<MonoBehaviour>().Where(m=>m).Select(m=>m.GetType().Name)));foreach(var r in page.root.GetComponentsInChildren<MeshRenderer>(true))b.AppendLine(" RENDERER "+V12FixRunner.Path(r.transform)+" size="+r.bounds.size);foreach(var mouse in page.root.GetComponentsInChildren<Template.OnMouseDownE>(true)){b.AppendLine(" MOUSE "+V12FixRunner.Path(mouse.transform));for(int i=0;i<mouse.mouseDown.GetPersistentEventCount();i++)b.AppendLine("  "+mouse.mouseDown.GetPersistentMethodName(i)+" -> "+mouse.mouseDown.GetPersistentTarget(i));}}foreach(var t in All<TMPro.TMP_Text>().Where(t=>t.text.IndexOf("TIA",StringComparison.OrdinalIgnoreCase)>=0))b.AppendLine("TIA "+V12FixRunner.Path(t.transform)+" text="+t.text);File.WriteAllText("Temp/V12/inspect.txt",b.ToString());}
 public static void Fix40(){var wind=All<FreeLabWindController>().Single();Require(wind.gridConnections.RequiredWires.Count==2,"Expected two grid leads");foreach(var wire in wind.gridConnections.RequiredWires){var so=new SerializedObject(wire);so.FindProperty("allowWhileOperating").boolValue=true;so.ApplyModifiedPropertiesWithoutUndo();}EditorSceneManager.SaveScene(SceneManager.GetActiveScene());Report("40","Only the two grid-input definitions allow connection/removal while powered. They were already absent from the power-on requirements; those requirements are preserved.");}
 public static IEnumerator Test40(){InteractionManager.Instance.SetFree();yield return 3f;var wind=FreeLabWindController.Instance;var profile=wind.profiles.Single(p=>p.experiment==4);var groups=profile.required.Concat(profile.alternatives.Select(a=>a.alternatives.First())).ToArray();foreach(var d in groups.SelectMany(g=>g.RequiredWires).Distinct())Require((bool)Call(wind.lab,"CreateConnection",d.endpointA,d.endpointB),"Failed base wire "+d.name);wind.mainEmergency.SetValue(true);wind.mainBreaker.SetValue(true);Require(wind.mainPower.CanEnable(wind.lab),"Grid input incorrectly required for power");wind.mainPower.GetComponent<Interaction>().Click();Require(wind.mainPower.Value,"Main power refused complete EXP4 without grid");wind.windEmergency.SetValue(true);wind.windBreaker.SetValue(true);wind.windPower.GetComponent<Interaction>().Click();Require(wind.windPower.Value,"Wind power refused EXP4 without grid");foreach(var d in wind.gridConnections.RequiredWires){d.endpointA.Interaction.Click();d.endpointB.Interaction.Click();Require(wind.lab.HasConnection(d.endpointA,d.endpointB),"Cannot connect optional grid lead live "+d.name);}foreach(var d in wind.gridConnections.RequiredWires){var wire=wind.lab.Connections.Single(w=>w.EndpointA==d.endpointA&&w.EndpointB==d.endpointB||w.EndpointA==d.endpointB&&w.EndpointB==d.endpointA);Require(wire.RemoveFromFreeLab(),"Cannot remove optional grid lead live "+d.name);}Require(wind.mainPower.Value&&wind.windPower.Value,"Optional lead removal shut power down");Require(!wind.lab.Connections.First().RemoveFromFreeLab(),"Unrelated powered wiring protection lost");Report("40","PASS actual Free EXP4 power clicks without grid leads; connect/remove both named grid leads while powered; unrelated live-wire removal remains blocked.");}
 public static void Fix59(){int count=0;foreach(var r in All<RheostatController>().Where(r=>V12FixRunner.Path(r.transform).StartsWith("Experiments/Exp ")&&V12FixRunner.Path(r.transform).Contains("/Steps/"))){foreach(var canvas in r.GetComponentsInChildren<Canvas>(true)){var before=canvas.transform.position;canvas.transform.SetParent(r.transform.parent,true);Require(Vector3.Distance(before,canvas.transform.position)<.0001f,"Canvas moved");count++;}}Require(count>0,"No rotating adjustment canvases found");EditorSceneManager.SaveScene(SceneManager.GetActiveScene());Report("59","Reparented "+count+" adjustment canvases beside their knob, preserving world pose and existing references/events.");}
 public static IEnumerator Test59(){var wind=All<FreeLabWindController>().Single();var r=wind.rheostats[0];Require(!r.adjustmentCanvas.transform.IsChildOf(r.controller.transform),"100-ohm symbols remain below rotating knob");var pose=r.adjustmentCanvas.transform.rotation;var position=r.adjustmentCanvas.transform.position;float previous=r.controller.CurrentResistance;r.controller.DecreaseValue();Require(r.controller.CurrentResistance<previous,"Rheostat stopped adjusting");Require(Quaternion.Angle(pose,r.adjustmentCanvas.transform.rotation)<.001f&&Vector3.Distance(position,r.adjustmentCanvas.transform.position)<.0001f,"Symbols rotate with knob");r.controller.IncreaseValue();Report("59","PASS Guided 100-ohm adjustment changes resistance while its canvas world rotation/position stay fixed.");yield break;}
 public static void Fix57(){var pv=SceneManager.GetActiveScene();var menu=EditorSceneManager.OpenScene("Assets/_Project/Scenes/Main Menu.unity",OpenSceneMode.Additive);foreach(var scene in new[]{pv,menu}){int count=0;foreach(var text in Resources.FindObjectsOfTypeAll<TMPro.TMP_Text>().Where(t=>t.gameObject.scene==scene&&t.text.Trim()=="TIA Portal Connection")){if(!V12FixRunner.Path(text.transform).Contains("Experiment 4:"))continue;var item=text.transform;while(item.parent&&item.name!="Document Item")item=item.parent;Require(item.name=="Document Item","Document item not found");item.gameObject.SetActive(false);count++;}Require(count==1,"Expected one EXP4 TIA item in "+scene.name+", found "+count);EditorSceneManager.SaveScene(scene);Report("57",scene.name+": removed TIA Portal Connection from EXP4 document list by disabling its layout item; other experiments unchanged.");}EditorSceneManager.CloseScene(menu,true);}
 public static IEnumerator Test57(){var text=All<TMPro.TMP_Text>().Single(t=>t.text.Trim()=="TIA Portal Connection"&&V12FixRunner.Path(t.transform).Contains("Experiment 4:"));var item=text.transform;while(item.parent&&item.name!="Document Item")item=item.parent;Require(!item.gameObject.activeSelf,"EXP4 TIA document still enabled");Report("57","PASS PV Lab EXP4 TIA document item remains disabled at runtime.");yield break;}
 public static void Fix60(){var wind=All<FreeLabWindController>().Single();for(int i=0;i<wind.pages.Length;i++){var page=wind.pages[i].root;var surface=page.GetComponentsInChildren<MeshRenderer>(true).OrderByDescending(r=>r.bounds.size.sqrMagnitude).First();var targets=page.GetComponentsInChildren<Bedo.Core.UI.MapCameraScreenshotButton_RT>(true);Require(targets.Length>0,"No screenshot component "+page.name);foreach(var target in targets){var so=new SerializedObject(target);so.FindProperty("captureSurface").objectReferenceValue=surface;so.FindProperty("defaultFileName").stringValue="Wind_EXP"+(i+1)+"_System";so.ApplyModifiedPropertiesWithoutUndo();}var primary=targets.First(t=>t.GetComponent<Collider>());int wired=0;foreach(var mouse in page.GetComponentsInChildren<Template.OnMouseDownE>(true).Where(m=>V12FixRunner.Path(m.transform).Contains("save screen"))){for(int j=mouse.mouseDown.GetPersistentEventCount()-1;j>=0;j--)if(mouse.mouseDown.GetPersistentMethodName(j)=="SaveScreenshot")UnityEditor.Events.UnityEventTools.RemovePersistentListener(mouse.mouseDown,j);UnityEditor.Events.UnityEventTools.AddPersistentListener(mouse.mouseDown,primary.SaveScreenshot);EditorUtility.SetDirty(mouse);wired++;}Require(wired>=2,"Missing physical Save Screen handlers");Report("60",page.name+": bound "+wired+" collider/mouse handlers to local screenshot component; capture surface="+surface.name+"; existing colliders retained.");}EditorSceneManager.SaveScene(SceneManager.GetActiveScene());}
 public static IEnumerator Test60(){var wind=All<FreeLabWindController>().Single();wind.blackScreen.SetActive(false);var parent=wind.monitors.transform;for(var t=parent;t;t=t.parent)t.gameObject.SetActive(true);foreach(var page in wind.pages){foreach(var other in wind.pages)other.root.SetActive(other==page);yield return .2f;var capture=page.root.GetComponentsInChildren<Bedo.Core.UI.MapCameraScreenshotButton_RT>(true).First(c=>c.GetComponent<Collider>());var mouse=capture.GetComponent<Template.OnMouseDownE>();Require(capture.isActiveAndEnabled&&mouse.isActiveAndEnabled&&capture.GetComponent<Collider>().enabled,"Inactive physical Save Screen");Call(mouse,"OnMouseDown");Require((bool)Get(capture,"capturing"),"Collider event did not start capture");capture.StopAllCoroutines();Set(capture,"capturing",false);var surface=(Renderer)Get(capture,"captureSurface");var png=Bedo.Core.UI.MapCameraScreenshotButton_RT.CaptureSurfaceToPngBytes(surface,512);Require(png!=null&&png.Length>2000,"Empty PNG "+page.root.name);var decoded=new Texture2D(2,2);decoded.LoadImage(png);var colors=decoded.GetPixels32();Require(colors.Any(c=>c.r>30||c.g>30||c.b>30),"Black PNG "+page.root.name);UnityEngine.Object.Destroy(decoded);File.WriteAllBytes("Temp/V12/"+page.root.name+".png",png);Report("60","PASS "+page.root.name+": physical mouse callback starts capture; monitor surface renders PNG ("+png.Length+" bytes). Native save dialog deliberately not opened by automated test.");}yield break;}
 public static Button GraphTab(Transform parent,string name,string label,Vector2 min,Vector2 max,TMPro.TMP_FontAsset font){var existing=parent.Find(name);if(existing)return existing.GetComponent<Button>();var go=new GameObject(name,typeof(RectTransform),typeof(UnityEngine.UI.Image),typeof(Button),typeof(BoxCollider),typeof(Template.OnMouseDownE));go.transform.SetParent(parent,false);var r=(RectTransform)go.transform;r.anchorMin=min;r.anchorMax=max;r.offsetMin=r.offsetMax=Vector2.zero;r.localPosition=new Vector3(r.localPosition.x,r.localPosition.y,-.1f);go.GetComponent<UnityEngine.UI.Image>().color=new Color(.86f,.86f,.86f,1);var collider=go.GetComponent<BoxCollider>();var canvas=(RectTransform)parent;collider.size=new Vector3(canvas.rect.width*(max.x-min.x),canvas.rect.height*(max.y-min.y),1);var textGO=new GameObject("Label",typeof(RectTransform),typeof(TMPro.TextMeshProUGUI));textGO.transform.SetParent(go.transform,false);var tr=(RectTransform)textGO.transform;tr.anchorMin=Vector2.zero;tr.anchorMax=Vector2.one;tr.offsetMin=tr.offsetMax=Vector2.zero;var text=textGO.GetComponent<TMPro.TextMeshProUGUI>();text.font=font;text.text=label;text.fontSize=15;text.alignment=TMPro.TextAlignmentOptions.Center;text.color=Color.black;text.raycastTarget=false;return go.GetComponent<Button>();}
 public static void Fix58(){var graphs=All<PVGraphController>().Where(g=>new SerializedObject(g).FindProperty("lineChartSpawnParent").objectReferenceValue is Transform t&&V12FixRunner.Path(t).Contains("Wind graph/")).ToArray();Require(graphs.Length==5,"Expected Guided1-4 and Free graph controllers");var first=new SerializedObject(graphs[0]);var voltage=(TMPro.TMP_Text)first.FindProperty("plottedYValuesText").objectReferenceValue;var scroll=voltage.GetComponentInParent<ScrollRect>(true);var parent=scroll.transform.parent;var current=parent.Find("DC Current Readings");if(!current){current=UnityEngine.Object.Instantiate(scroll.transform,parent,false);current.name="DC Current Readings";}var rect=(RectTransform)current;rect.anchorMin=new Vector2(.24f,.20f);rect.anchorMax=new Vector2(.34f,.74f);rect.sizeDelta=((RectTransform)scroll.transform).sizeDelta;rect.anchoredPosition=((RectTransform)scroll.transform).anchoredPosition;var values=current.GetComponentsInChildren<TMPro.TMP_Text>(true).Single(t=>t.name=="Values");values.text="";var voltageTab=GraphTab(parent,"Voltage Graph Tab","DC Voltage",new Vector2(.40f,.68f),new Vector2(.64f,.735f),voltage.font);var currentTab=GraphTab(parent,"Current Graph Tab","DC Current",new Vector2(.66f,.68f),new Vector2(.90f,.735f),voltage.font);foreach(var button in new[]{voltageTab,currentTab}){var br=(RectTransform)button.transform;br.anchorMin=new Vector2(button == voltageTab ? 0.40f : 0.66f,.68f);br.anchorMax=new Vector2(button == voltageTab ? 0.64f : 0.90f,.735f);br.offsetMin=br.offsetMax=Vector2.zero;br.anchoredPosition=new Vector2(73.4f,0);button.GetComponent<BoxCollider>().size=new Vector3(((RectTransform)parent).rect.width*.24f,((RectTransform)parent).rect.height*.055f,1);button.GetComponent<Template.OnMouseDownE>().mouseDown=new UnityEngine.Events.UnityEvent();}voltageTab.interactable=false;currentTab.interactable=true;foreach(var g in graphs){UnityEditor.Events.UnityEventTools.AddPersistentListener(voltageTab.GetComponent<Template.OnMouseDownE>().mouseDown,g.ShowVoltageGraph);UnityEditor.Events.UnityEventTools.AddPersistentListener(currentTab.GetComponent<Template.OnMouseDownE>().mouseDown,g.ShowCurrentGraph);var so=new SerializedObject(g);so.FindProperty("plottedCurrentValuesText").objectReferenceValue=values;so.FindProperty("voltageGraphTab").objectReferenceValue=voltageTab;so.FindProperty("currentGraphTab").objectReferenceValue=currentTab;so.ApplyModifiedPropertiesWithoutUndo();}EditorSceneManager.SaveScene(SceneManager.GetActiveScene());Report("58","Added shared DC-current scrolling column and Voltage/Current graph tabs; assigned all five wind graph controllers. Current comes from the same live WindReading as the meters. Existing RPM/voltage export format retained.");}
 public static IEnumerator Test58(){var windUI=All<FreeLabWindController>().Single();windUI.blackScreen.SetActive(false);windUI.monitors.SetActive(false);for(var t=windUI.graphPage.transform;t;t=t.parent)t.gameObject.SetActive(true);yield return .2f;var graph=All<PVGraphController>().Single(g=>g.IsWindExperimentActive);var binder=(PVGuidedDataBinder)Get(graph,"guidedDataBinder");var speed=(WindTurbineSpeedController)Get(binder,"windSpeedController");speed.TurnOn();speed.SetSpeed(600);graph.UpdateWindMeasurement();Require(binder.TryGetWindReading(out var reading),"No live reading");var currents=(System.Collections.Generic.List<float>)Get(graph,"plottedCurrentValues");Require(currents.Count>0&&Mathf.Abs(currents.Last()-reading.dcCurrent)<.0001f,"Current differs from meter/model");var currentText=(TMPro.TMP_Text)Get(graph,"plottedCurrentValuesText");Require(currentText&&currentText.text.Split('\n').Last()==reading.dcCurrent.ToString("0.##"),"Current row missing");Call(((Button)Get(graph,"currentGraphTab")).GetComponent<Template.OnMouseDownE>(),"OnMouseDown");var chart=(XCharts.Runtime.LineChart)Get(graph,"lineChart");Require(chart.GetChartComponent<XCharts.Runtime.YAxis>().axisName.name=="DC current (A)","Wrong current axis");Require(chart.GetSerie("Current curve")!=null&&chart.GetSerie("Current curve").data.Count==currents.Count,"Current graph lost recorded points");yield return .2f;var surface=windUI.graphPage.GetComponentsInChildren<MeshRenderer>(true).OrderByDescending(r=>r.bounds.size.sqrMagnitude).First();File.WriteAllBytes("Temp/V12/current-graph.png",Bedo.Core.UI.MapCameraScreenshotButton_RT.CaptureSurfaceToPngBytes(surface,1200));graph.ShowVoltageGraph();Require(chart.GetSerie("Speed curve")!=null&&chart.GetSerie("Speed curve").data.Count==currents.Count,"Voltage graph lost points on switch");var xs=((TMPro.TMP_Text)Get(graph,"plottedXValuesText")).GetComponentInParent<ScrollRect>(true);var ys=((TMPro.TMP_Text)Get(graph,"plottedYValuesText")).GetComponentInParent<ScrollRect>(true);var cs=currentText.GetComponentInParent<ScrollRect>(true);cs.content.anchoredPosition=new Vector2(0,35);cs.onValueChanged.Invoke(Vector2.zero);Require(Mathf.Abs(xs.content.anchoredPosition.y-35)<.01f&&Mathf.Abs(ys.content.anchoredPosition.y-35)<.01f,"Three columns not synchronized");graph.ClearRuntimeGraph();Require(currents.Count==0&&currentText.text=="","Clear left current rows");Report("58","PASS live current matches meter/model; current and voltage charts retain identical row counts when switching; all three columns scroll together; Clear clears current rows.");yield break;}
 public static void Dump(){if(SceneManager.GetActiveScene().name!="PV Lab")EditorSceneManager.OpenScene("Assets/_Project/Scenes/PV Lab.unity");var b=new System.Text.StringBuilder();foreach(var c in All<MonoBehaviour>().Where(c=>c)){if(!new[]{"WindMonitorTabs","PVGraphController","FreeLabWindController","MapCameraScreenshotButton_RT","ExperimentMenuTabHighlight","RheostatController","MultipleChoiceQuiz"}.Contains(c.GetType().Name))continue;b.AppendLine("--- "+GlobalObjectId.GetGlobalObjectIdSlow(c)+" "+V12FixRunner.Path(c.transform)+" "+c.GetType().Name);var so=new SerializedObject(c);var p=so.GetIterator();while(p.NextVisible(true)){if(p.propertyType==SerializedPropertyType.ObjectReference&&p.objectReferenceValue is Component v)b.AppendLine(p.propertyPath+" = "+V12FixRunner.Path(v.transform)+" #"+GlobalObjectId.GetGlobalObjectIdSlow(v));else if(p.propertyType==SerializedPropertyType.ObjectReference&&p.objectReferenceValue is GameObject g)b.AppendLine(p.propertyPath+" = "+V12FixRunner.Path(g.transform)+" #"+GlobalObjectId.GetGlobalObjectIdSlow(g));}}File.WriteAllText("Temp/V12/refs.txt",b.ToString());}
